GimCorpus.put(370,0,[[1,1,"מצות עשה להפריש כל פטר רחם הזכרים וכו'. מפורש בתורה פ' בא אל פרעה ופ' ראה.",1,0],[1,1,"ומ\"ש בין שהיו טריפות:",2,0],[1,2,"ומ\"ש ופדיונם לכהנים. בפרק רביעי דחלה (משנה ט').",1,0],[1,2,"ומה שכתב ובכור בהמה טהורה נשחט בעזרה וכו'. משנה בפ' איזהו מקומן (זבחים דף נ״ו:):",2,0],[1,3,"בכור בהמה טהורה שהוא בעל מום וכו'. פשוט בכמה מקומות מהם סוף פ' איזהו מקומן (זבחים דף נ״ז) ובפ' ב״ש:",1,0],[1,3,"ומ\"ש אם רצה אוכלו בכ\"מ. דע\"כ לא שנינו בס\"פ איזהו מקומן שהבכור נאכל בכל העיר אלא בתם אבל בעל מום נאכל בכל מקום.",2,0],[1,3,"ומ\"ש או מוכרו. בריש מעשר שני (משנה ב').",3,0],[1,3,"ומ\"ש או מאכילו למי שירצה אפי' לנכרי. במשנה פ\"ה דבכורות (דף לב:) פלוגתא דתנאי ופסק כב\"ה.",4,0],[1,3,"ומ\"ש והרי הוא נכסי כהן. רפ\"ב דבכורים תנן דבכורים נכסי כהן ומשמע לרבינו דבכור בכלל בכורים הוא ובסוף מסכת בכורים (פ\"ג מי\"ב) תנן ולמה אמרו הבכורים כנכסי כהן שהוא קונה מהם עבדים וקרקעות ובהמה טמאה וב\"ח נוטלם בחובו ואשה בכתובתה:",5,0],[1,4,"מצוה להקדיש בכור בהמה טהורה וכו'. בסוף המקדיש שדהו (דף נ\"ט.):",1,0],[1,5,"מצות בכור בהמה טהורה נוהגת בארץ ובח״ל. כך היא הנוסחא האמיתית והכי משמע בסוף פ״ג דתמורה (דף כ״א) ובפ' אלו טריפות (חולין דף מ״ד:) אמרינן דאמרה ליה בת רב חסדא לרבא אבא שרי בוכרא ולא זבן מיניה בשרא ובפ' קמא דבכורות (דף ג':) רב מרי בר רחל ה״ל ההיא חיותא דהוה מקני לאודנייהו לנכרי ובפרק אין צדין (ביצה דף כ״ז:) ההוא גברא דאייתי בוכרא קמיה דרבא:",1,0],[1,5,"ומ\"ש ואין מביאין בכורות מח\"ל שנאמר ואכלת לפני ה' אלהיך וגו' אלא יאכל במומו ואם הביא אין מקבלין ממנו ולא יקרב אלא יאכל במומו. בספ\"ג דתמורה (דף כ\"א) פלוגתא דתנאי ופסק כר\"ע. ודע שבספרי רבינו היה כתוב מצות בכור בהמה טהורה אינה נוהגת אלא בארץ וע\"פ זה השיגו הראב\"ד וכתב טעות היא זו גם הרמב\"ן בהל' בכורות תמה עליו והקשה עליו כמה קושיות וכן הרשב\"א והר\"ן בתשובה וכולם ספר מוטעה נזדמן להם בדברי רבינו והגירסא שכתבתי בדבריו היא הכתובה בספרינו והיא הנוסחא האמיתית:",2,0],[1,6,"ומצוה זו נוהגת וכו'. בסוף שקלים (פ\"ח מ\"ח) ובפירקא בתרא דבכורות (דף נ\"ג) והכי איכא למילף מהנך שהבאתי גבי נוהגת בח\"ל.",1,0],[1,6,"ומ״ש ואינה נוהגת במוקדשין כשהן בקדושתן קודם שיפדו בין קדשי מזבח בין קדשי בדק הבית. משנה בפ' הזרוע (חולין דף ק״ל) ופ״ב דבכורות (דף י״ד). ודע ששנינו במשנה הנזכרת דהא דאמרינן דקודם שיפדו פטורים מן הבכורה הא אחר שנפדו חייבים ה״מ בשקדם מום קבוע להקדשן אבל אם קדם הקדשן את מומן או מום עובר להקדשן ולאחר מכאן נולד להם מום קבוע להקדשן אפי' אחר שנפדו פטורים מן הבכורה וביאר זה רבינו בפ' ה':",2,0],[1,7,"הכל חייבים בבכורה כהנים וכו'. משנה בפ\"ב דבכורות (דף י\"ג).",1,0],[1,7,"ומ\"ש ואע\"פ שהבכור לכהן אם נולד לו בכור מקריב דמו ואימוריו וכו'. פשוט הוא ע\"פ מה שנתבאר שהכהנים חייבים.",2,0],[1,7,"ומ\"ש אבל בכור אדם ובכור בהמה טמאה כהנים ולוים פטורין. משנה בפ\"ק (דף ד') ופ\"ב דבכורות (דף י\"ג):",3,0],[1,8,"הבכור נאכל בתוך שנתו וכו'. משנה בפ' עד כמה (בכורות דף כ״ו:).",1,0],[1,8,"ומה שכתב מאימתי מונה לו וכו' עד אבל אם לא ידע בודאי שכלו לו חדשיו מונה לו מיום שמיני. בפ\"ק דר\"ה (דף ו' ז'):",2,0],[1,9,"נולד לו מום בתוך שנתו וכו'. משנה בפרק עד כמה (בכורות דף כ״ח:).",1,0],[1,9,"ומה שכתב נולד לו מום בסוף שנתו וכו'. שם בדף כ\"ח.",2,0],[1,9,"וומה שכתב נולד לו מום אחר שנתו וכו'. משנה שם:",3,0],[1,11,"הבכור בזמן הזה וכו' עד מקיימו שלשים יום. שם:",1,0],[1,11,"מצאתי כתוב ועד שלא נראה לחכם רשאי לקיימו. כן הוא לשון הברייתא ופירושו חייב לקיימו דהא כל עוד שלא נפל בו מום א\"א לשחטו וע\"כ יקיימנו ואטו דתנא סיפא אם נולד לו מום וכו' רשאי תנא ברישא רשאי עכ\"ל. והתוס' כתבו שפירוש זה דחוק:",2,0],[1,12,"שנה של בכור היא שנת לבנה תמימה וכו'. פרק קמא דר\"ה (דף י\"ז) ופ\"ה דערכין (דף ל\"א) פלוגתא דתנאי ופסק כחכמים:",1,0],[1,12,"נולדו לו שני טלאים וכו'. מימרא פ\"ק דערכין (דף ל\"א:):",2,0],[1,13,"עבר ואיחר הבכור לאחר שנתו וכו' עד משנה לחבירתה. פרק קמא דר\"ה (דף ה':):",1,0],[1,15,"אין נותנין את הבכור לכהן כשיולד וכו' עד הרי זה נותנו לו. משנה וגמרא בריש פרק עד כמה (בכורות דף כ״ו:):",1,0],[1,15,"ויראה לי שהבכור נותן לכל כהן שירצה. נראה דהיינו לומר דטובת הנאה לבעלים:",2,0],[1,16,"כהן שאכל כזית מבכור תמים וכו' וכן זר שאכל כזית מבכור וכו'. בפרק אלו הן הלוקין (מכות דף י״ז):",1,0],[1,17,"הבכור אין פודין אותו וכו'. בר״פ כל פסולי המוקדשין (בכורות דף ל״א:) ופ״ק דתמורה (דף ה':):",1,0],[1,17,"וכן אין מוכרין אותו כשהוא תם וכו' עד ואע\"פ שהוא תמים. בפ\"ק דתמורה (דף ח':).",2,0],[1,17,"ומ\"ש בין לכהן בין לישראל. שם (דף ח':) אמר רב חסדא ל\"ש (דמותר למכרו תמים) אלא כהן לכהן אבל כהן לישראל אסור וכו' מפני שנראה ככהן המסייע בבית הגרנות, ובתר הכי בעובדא דמר זוטרא איקלע לבי רב אשי אמרינן דלא סבירא להו הא דרב הונא בריה דרב יהושע דקאמר על מילתיה דרב חסדא, וכיון דבי רב אשי דבתרא הוא סברי דאפילו לישראל שרי ומר זוטרא נמי משמע דקבלה מינייהו הכי נקטינן:",3,0],[1,18,"ומ״ש בכור בעל מום יש לכהן למוכרו בכל זמן וכו'. בר״פ כל פסולי המוקדשין (בכורות דף ל״א) ובפ״ק דתמורה (דף ה').",1,0],[1,18,"ומ\"ש וכשהוא מוכר בשר בכור בעל מום מוכרו בבית אבל לא בשוק. משנה ר\"פ כל פסולי המוקדשין שם.",2,0],[1,18,"ומ\"ש אבל בשר בכור תמים אינו נמכר וכו'. פשוט הוא והכי משמע בפ\"ק דתמורה שם.",3,0],[1,18,"ומה שכתב וכהנים שנמנו על הבכור מותרים לשקול מנה כנגד מנה בבכור. ר\"פ כל פסולי המקודשין (דף ל\"א) תנן שוקלין מנה כנגד מנה בבכור ומפשטא משמע דארישא קאי דקתני בבכור בעל מום אינו נשקל בליטרא ומדברי רבינו כאן נראה שהוא מפרשה בבכור תמים בזמן המקדש:",4,0],[1,19,"המפשיט בכור בעל מום וכו'. בספ\"ד דתמורה (דף כ\"ד) תניא דאין מרגילין בבכור ולא בפסולי המוקדשין ואוקימנא לה בתנאי דלית הלכתא כוותייהו. ומה שאמרו שם במערבא אמרי מפני שנראה כעובד עבודה בקדשים ר\"י בר אבין אמר גזירה שמא יגדל מהם עדרים עדרים מפרש רבינו דאדר\"א בר\"ש קאי ולא כדפירש\"י והרא\"ש:",1,0],[2,3,"כל המומים הקבועים וכו' אם נפל אחד מהם בבכור הרי זה נשחט עליו בכל מקום וכו' עד ירעה עד שיפול בו מום. משנה פרק על אלו מומין (בכורות דף מ״א):",1,0],[2,4,"יוצא דופן והבא אחריו וכו'. משנה פרק ב' דבכורות (דף י\"ט) וכרבי עקיבא.",1,0],[2,4,"ומה שכתב אפילו יצאת נקבה דרך דופן וכו'. שם בגמרא:",2,0],[2,5,"בכור שהוא אנדרוגינוס וכו'. משנה בסוף פרק על אלו מומין (בכורות דף מ״א) ופסק כחכמים:",1,0],[2,5,"נולד טומטום הרי זה ספק בכור וכו'. מימרא דר\"ח שם.",2,0],[2,5,"ומה שכתב בין שהטיל מים ממקום זכרות וכו'. הכי משמע התם בגמרא דלרב חסדא לא שאני ליה בטומטום בין מטיל ממקום זכרות למטיל ממקום נקבות הרי זה ספק בכור וכמו שכתבתי בספר בית יוסף ליורה דעה. ובקצת ספרי רבינו כתוב הרי זה בכור בין שהטיל האנדרוגינוס ממקום זכרות ט\"ס הוא וצריך למחוק תיבת האנדרוגינוס משום דההוא אין בו קדושה כלל וכך מצאתי בספר כתיבת יד. ויש לתמוה על רבינו שפסק דמטיל מים ממקום זכרות נמי ספיקא ויאכל במומו לבעלים והא בין לרב חסדא בין לר\"ל זכר הוי והכי משמע דהוי לרבי אלעאי נמי. ונראה שטעמו משום דכיון דרב חסדא סתם ואמר דטומטום ספיקא הוא ולא מפליג הכי נקטינן ולא חיישינן למאי דאמרינן מטיל מים במקום זכרות כולי עלמא לא פליגי דזכר הוא משום דההיא דחייה בעלמא היא כי היכי דלא תיקום כתנאי:",3,0],[2,6,"רחל שילדה כמין עז וכו'. משנה בפ\"ב דבכורות (דף ט\"ז:):",1,0],[2,6,"ומ\"ש והוא בעל מום קבוע וכו'. בפ\"ק דבכורות (דף ג') מימרא דר' יוחנן.",2,0],[2,6,"ומ\"ש אפילו פרה שילדה כמין חמור וחמור שילדה כמין סוס פטור מן הבכורה. משנה בפ\"ק דבכורות (דף ה') ובגמ' (דף ו') איבעיא להו פרה שילדה כמין חמור ויש בו מקצת סימנים מהו וכו' את\"ל כיון דאידי ואידי בני מיקדש בבכורה קדוש חמור שילדה כמין סוס מהו וכו' את\"ל כיון דמין טמאה הוא קדוש פרה שילדה כמין סוס מהו הכא ודאי הא טמאה והא טהורה הא בת מיקדש בבכורה והא לאו בת מיקדש בבכורה או דילמא סימנים מילתא היא ולא איפשיטא. וכבר נודע דרך רבינו לפסוק כאת\"ל ומפני כך פסק בפרה שילדה כמין חמור שאם יש בו מקצת סימני פרה הרי זה בכור לכהן ולענין חמור שילדה כמין סוס דאמרינן ביה את\"ל כיון דמין טמאה הוא קדוש אע\"פ שלא הזכירו כאן בסוף הלכות בכורים כתב שאם יש בו מקצת סימני חמור חייב ולענין פרה שילדה כמין סוס ויש בו קצת סימני פרה כיון דלא איפשיטא פסק שהוא ספק בכור. ומ\"מ מ\"ש בבבא זו אע\"פ שיש בו מקצת סימני פרה אינו נוח לי דמפשטא דלישנא איכא למשמע דאין בו מקצת סימני פרה ויש בו מקצת סימני פרה שוין הם דשניהם ספק ואינו כן שאם אין בו סימני פרה ודאי אינו בכור כלל וצ\"ל שלא השוום אלא לענין שאינם בכור ודאי אבל הא כדאיתיה והא כדאיתיה שזה אינו בכור כלל וזה ספק וזה פשוט.",3,0],[2,6,"ומ\"ש רבינו גבי ספק בכור יאכל במומו לבעלים. הוא מדקי\"ל המע\"ה.",4,0],[2,6,"ומ\"ש ואם תקפו כהן אין מוציאים מידו. טעמו מדאמרינן בפ\"ק דמציעא (דף ז':) אעובדא דההיא מסותא דהוו מינצו עלה בי תרי א\"ר המנונא מתני' היא ספק בכורה המע\"ה והא הכא דאם תקפו כהן אין מוציאין מידו וכי לא תקפו אסור בגיזה ועבודה. אבל קשה דהא בתר הכי אמרינן א\"ל רבה וכו' לעולם אימא לך תקפו כהן מוציאין אותו מידו ואפ\"ה אסורים בגיזה ועבודה וכו' א\"ל רב חנניא לרבה תניא דמסייע לך. והשתא למה דחה רבינו דברי רבה ורב חנניא וברייתא ופסק כרב המנונא. וי\"ל דהא דאמר רבה לעולם אימא לך תקפו כהן מוציאין מידו ואפ\"ה אסור בגיזה ועבודה וכו' סובר רבינו דחייה בעלמא היא וסייעתא דרב חנניא לאו סייעתא כולי האי דכיון דברשות ישראל הוא והמע\"ה אע\"ג דאם תקפו כהן אין מוציאין מידו לא נפיק מידי ממונו של ישראל ושפיר יכול לפטור עצמו בו. ובתשובות הרשב\"א סי' שי\"א כתוב שנשאל על זה והשיב באמת גם לי נראה פשיטותא של הלכה כן אלא דבעינן למשכוני נפשין אדרבינו לחזר אחר זכותו והשתדל להראות פנים לדברי רבינו:",5,0],[2,7,"המטיל מום בבכור וכו'. במשנה פרק כל פסולי המוקדשין (בכורות דף ל״ד) פלוגתא דתנאי ופסק כחכמים.",1,0],[2,7,"ומ\"ש ואם מת זה החוטא מותר לבנו לשוחטו וכו'. שם בעיא דאיפשיטא:",2,0],[2,8,"הרגיל לבכור שיפול בו מום וכו'. בברייתא פרק כל פסולי המוקדשין שם.",1,0],[2,8,"ומ\"ש או שהלך בין ברזל וכו'. מעובדא דרבי צדוק דבסמוך איכא למילף הכי ולישנא דאו שהלך היינו לומר שהוליכו הוא שם שאם הלך מעצמו ודאי דלא הוי מרגיל שיפול בו מום.",2,0],[2,8,"ומ״ש או שאמר לנכרי להטיל בו מום וכו' זה הכלל כל מום שנעשה לדעתו וכו'. משנה פרק כל פסולי המוקדשין (בכורות דף ל״ה):",3,0],[2,9,"ומ\"ש אמר אילו נפל מום בבכור זה הייתי שוחטו וכו'. שם במשנה מעשה בזכר של רחלים זקן ושערו מדולדל וראהו קסדור אחד אמר מה טיבו של זה אמרו לו בכור הוא ואינו נשחט אא\"כ היה בו מום נטל פגיון וצרם אזנו ובא מעשה לפני חכמים והתירו ואחר שהתירו הלך וצרם באזני בכורות אחרים ואסרום:",1,0],[2,10,"ראינוהו שעשה מעשה המרגיל וכו' כיצד כגון שנתן לו שעורים במקום דחוק וכו'. שם (דף ו') בעובדא דר' צדוק:",1,0],[2,11,"היה בכור רודף את האדם וכו'. משנה שם (דף ל\"ה).",1,0],[2,11,"ומ\"ש ואפילו בעט בו מפני שרדפו מקודם וכו'. שם תרי לישני דרב פפא ופסק כלישנא בתרא וכ\"ג הרמב\"ן. וכתב הרא\"ש ולא ידענא טעמא מאי דבשל תורה הוא ואפשר דהיינו טעמא דאע\"ג דאיסור דהטלת מום הוי דאורייתא מה שאינו נאכל באותו מום הוי מדרבנן עכ\"ל:",2,0],[2,12,"קטנים שהטילו מום בבכור דרך שחוק וכו' עד לא ישחט עליו. משנה שם:",1,0],[2,13,"בכור שאחזו דם יקיז וכו'. משנה שם (ל\"ב:) פלוגתא דתנאי וכן בברייתא ופסק כר\"ש דמתניתין ודברייתא דהכי איפסיקא הלכתא בגמ':",1,0],[2,14,"מותר להטיל מום וכו'. מימרא דרב יהודה בפירקא קמא דבכורות (דף ג').",1,0],[2,14,"ומה שכתב בד\"א בזמן הזה וכו'. ריש פ' כיצד מערימין (דף מ'):",2,0],[2,15,"עד שהעיד מפי עד אחר וכו' אפילו אשה נאמנת וכו'. בפ' כל פסולי המוקדשין (בכורות דף ל״ו):",1,0],[2,16,"כל המומין הראויים לבא בידי אדם וכו'. משנה שם (דף ל\"ה) כל המומין הראויים לבא בידי אדם רועים ישראל נאמנים רועים כהנים אינם נאמנים רשב\"ג אומר נאמן הוא על של חבירו ואינו נאמן על של עצמו ר\"מ אומר החשוד על הדבר לא דנו ולא מעידו. ובגמרא איפליגו ר\"י ורבי אלעזר בפירושא דמתני' חד אמר רועי ישראל בי כהנים נאמנים וכו' רועי כהנים בי ישראל אינם נאמנים מימר אמר כיון דקא טרחנא ביה לא שביק לדידי ויהיב לאחריני וה\"ה כהן לכהן דחיישינן לגומלין ואתא רשב\"ג למימר נאמן הוא על של חבירו ואינו נאמן על של עצמו ואסיקנא דהלכה כרשב\"ג. וכתב הרא\"ש רועה כהן בשל ישראל מהימן דלאו של עצמו הוא והכי חזינא בפירושא דרבוותא ואיכא מאן דאמר דפסק דלא מהימן והיינו כלישנא קמא דאמר רועי כהנים בשל ישראל אינם נאמנים וס\"ל דלא פליג רשב\"ג אלא אמאי דמחסרא דמתני' דהיינו כהן לכהן דלא חייש איהו לגומלין אבל רועה כהן בישראל לא פליג דכיון דסבר לא שביק לדידיה בשל עצמו דמי והך סברא לא מעליא היא דכיון דאפילו בנו ובתו מהימני סברא הוא דכ\"ש רועי כהן בשל ישראל ועוד דלא מסתברא דקאי אמאי דמחסרא מתני' דוקא ולא קאי אעיקר מתני' ועוד בר מן דין הא ללישנא בתרא רועי כהן בי ישראל אפילו לת\"ק הימוני מהימן וכיון דפלוגתא דלישני הוא ליכא איסורא אלא גזירה דרבנן גרידא לקולא נקטינן ועוד דמתני' כפשוטה אתיא כי האי לישנא וללישנא קמא צריך לחסורה הילכך האי לישנא עדיף ונקטינן מינה דרועי כהנים בי ישראל נאמנין וכ\"פ הלכתא הרמב\"ן ז\"ל עכ\"ל. ואני אומר שמתוך דבריו נתבאר טעמו של רבינו שהוא כההיא סברא שכתב ברישא והקושיא שהקשה על אותה סברא לא מכרעי דאפשר לתרוצינהו:",1,0],[2,17,"כהן שהעיד לכהן אחר וכו'. שם במשנה וגמרא ופסק כרבן שמעון בן גמליאל.",1,0],[2,17,"ומה שכתב שכל הכהנים חשודים להטיל מום בבכור וכו'. שם.",2,0],[2,17,"ומ\"ש כל, כלומר אפילו הוא חבר וכמו שנתבאר בפרק זה.",3,0],[2,17,"ומ\"ש אפילו בניו ובני ביתו של כהן מעידים לו על הבכור אבל לא אשתו וכו'. שם:",4,0],[2,18,"בכור שהיה ביד כהן וכו'. זהו פירוש מה ששנינו בפרק הנזכר (דף ל\"ו) נאמן הכהן לומר הראיתי בכור זה ובעל מום הוא:",1,0],[2,19,"וכן נאמן הכהן לומר על בכור בעל מום וכו'. מימרא דרב יהודה (דף ל\"ו). וכתב הרא\"ש דדוקא באומר ישראל פלוני נתנו לי במומו אבל אם אמר ישראל סתם שאינו מזכירו לא. ובספר ב\"י ליורה דעה סי' שי\"ד כתבתי טעמו וטעם רבינו:",1,0],[3,1,"אין שוחטין את הבכור אלא ע\"פ מומחה וכו'. בפ\"ק דסנהדרין (דף ה').",1,0],[3,1,"ומ\"ש אפילו היה מום גדול וגלוי לכל וכו'. יתבאר בסמוך.",2,0],[3,1,"ומ״ש וכל הבכורות אדם רואה חוץ מבכורות עצמו. בסוף פרק ב' דנגעים ובסוף פרק עד כמה (בכורות דף ל״א.) ומוקמינן לה ביחיד מומחה דאילו בשלשה יכול להיות אחד מהשלשה דלא חשידי כלום בשבילו וכך הם דברי רבינו:",3,0],[3,2,"אם אין שם מומחה וכו'. במשנה ס״פ כל פסולי המוקדשין (בכורות דף ל״ו:) פלוגתא דתנאי ואיפסיקא בגמרא הלכתא כת״ק.",1,0],[3,2,"ומ\"ש וכן בכור שיצא ח\"ל ונפל בו מום מובהק וכו'. מימרא שם התרת בכור בח\"ל ע\"פ שלשה בני הכנסת ובמומים מובהקים. וכתב רבינו שיצא ח\"ל לרבותא דאע\"פ שנולד בארץ אינו צריך מומחה וכל שכן אם נולד בח\"ל:",2,0],[3,3,"אין רואים את הבכור לישראל וכו' עד לגזול מתנות כהונה. מימרא דרב יהודה שם.",1,0],[3,3,"ומ\"ש לפיכך אם היה חכם וכו'. נלמד ממה שיבא בסמוך.",2,0],[3,3,"ומ\"ש היה המום גלוי לכל וכו'. שם:",3,0],[3,4,"השוחט את הבכור ואח״כ הראה את מומו וכו'. במשנה פ' עד כמה (בכורות דף כ״ח) פלוגתא דתנאי ופסק כר״מ וכ״כ הרא״ש בשם בעל הלכות גדולות והרמב״ן משום דהלכה כר״מ בגזירותיו:",1,0],[3,5,"בכור שהיתה לו ביצה אחת ושני כיסים וכו'. במשנה פ' על אלו מומין (בכורות דף מ') פלוגתא דתנאי ופסק כר״ע:",1,0],[3,6,"מי שאינו מומחה וראה את הבכור וכו'. משנה בפרק עד כמה (בכורות דף כ״ח).",1,0],[3,6,"ומה שכתב וכמה משלם וכו'. שם בגמרא [עמוד ב'].",2,0],[3,6,"ומ\"ש מפני שקנסו את בעל הבהמה וכו'. שם מ\"ט וכו' אמר רב הונא בר מנוח וכו' משום גזירת מגדלי בהמה דקה נגעו בה. ופירש\"י משום גזירת בהמה דקה נגעו בה מום טורח מגדלי בהמה דקה שיש בה טורח גדול לגדלה וזה שהתיר הבכור הצילו לכהן מטורח גדול דשמא אם הראהו לאחר לא היה מתירו לו והיה לו עוד טיפול מרובה עד שיפול בו מום להכי נגעו בו דאינו משלם אלא רביע. ל\"א מפני מגדלי בהמה דקה שעוברים על דברי חכמים כדתנן אין מגדלין בהמה דקה בארץ ישראל קנסו חכמים דלא לישקול אלא רביע עכ\"ל. והראב\"ד כתב א\"א אין כאן קנס וכו'. ודברי רבינו כלשון אחרון של רש\"י:",3,0],[3,7,"הנוטל שכרו להיות רואה בכורות וכו'. משנה שם.",1,0],[3,7,"ומ\"ש ולא יטול שכר על בהמה זו וכו'. שם בגמרא (דף כ\"ט):",2,0],[3,8,"החשוד על הבכורות וכו'. משנה שם.",1,0],[3,8,"ומ\"ש אפילו של נקבה. פלוגתא שם במשנה ופסק כת\"ק.",2,0],[3,8,"ומ\"ש ואין לוקחים ממנו צמר וכו' עד ועורות עבודים וכו'. שם במשנה ובגמרא:",3,0],[3,9,"השוחט את הבכור ומכרו וכו'. משנה שם (דף ל\"ז) וכתב רבינו דין זה פרק ט\"ז מהל' מכירה:",1,0],[3,10,"בכור שנמצא טריפה וכו'. בפ' טבול יום (זבחים ק\"ג) תנן כל הקדשים שאירע בהם פיסול קודם להפשטן אין עורותיהם לכהנים לאחר הפשטן עורותיהם לכהנים א\"ר חנינא סגן הכהנים מימי לא ראיתי עור שיוצא לבית השריפה אמר ר\"ע מדבריו למדנו שהמפשיט את הבכור ונמצא טריפה שיאותו הכהנים בעורו וחכ\"א אין לא ראינו ראיה אלא יוצא לבית השריפה. ובגמרא (דף ק\"ד) א\"ר חייא בר אבא אר\"י הלכה כר\"ע ואף ר\"ע לא אמר אלא כשהתירו מומחה אבל לא התירו מומחה לא והלכתא כחכמים בשר בקבורה והעור בשריפה ומפרש רבינו דחכמים ל\"פ אר\"ע דר\"ע מיירי בבעל מום וחכמים מיירו בתמים והלכה כר\"ע והלכה כחכמים.",1,0],[3,10,"ומ\"ש רבינו אחר שהופשט. לומר דאילו קודם שהופשט העור כבשר בקבורה כדאיתא בברייתא בגמרא:",2,0],[3,11,"הבכור שנאכל בשרו וכו' כך נהנים בגיזותיו. כן משמע במשנה (דף כ\"ה:) בפ\"ג דבכורות.",1,0],[3,11,"ומ\"ש אבל כל צמר שנגזז ממנו כשהוא חי אפי' נשר אסור בהנאה אפי' אחר שחיטתו. כלומר ע\"פ מומחה שהותר הצמר שבעור אסור הצמר שנשר ממנו כשהוא חי ואצ\"ל אחר מיתתו שאסור הצמר שבעור וכבר נתבאר בפ\"א מהל' מעילה.",2,0],[3,11,"ומ\"ש וכבר ביארנו בהלכות מעילה וכו'. בפ' הנזכר:",3,0],[3,12,"בכור [שהיה בו צמר] מדובלל וכו'. שם.",1,0],[3,12,"ומה שכתב והוא הצמר שעיקרו הפוך כלפי ראשו. שם (דף כ\"ו:) פלוגתא דאמוראי ופסק כריש לקיש דהוא מאריה דגמרא טפי מרב נתן בר אושעיא ועוד דרבי אלעזר נמי ס\"ל כר\"ל ועוד דר' אלעא פריש טעמא דר\"ל משמע דכוותיה ס\"ל ועוד דטעמא דיהיב ר' אלעא טעמא דמסתבר הוא:",2,0],[3,13,"גיזת בכור אפילו בעל מום וכו'. בספ\"ג דבכורות (דף כ\"ה:) תניא בעלי מומין אסורים בכל שהו ומפרש לה ר\"נ בגיזת בכור בעל מום שנתערבה בגיזי חולין ואע\"ג דר' יוסי פליג ואמרינן בגמרא מאן ת\"ק ר' יהודה וה\"ל למיפסק כר' יוסי לגבי ר' יהודה הא איפסיקא התם בגמ' הלכה כר' יהודה אבל איכא למידק דאמרינן התם דאמרוה להא דר\"נ קמיה דר' ירמיה וקרי להו בבלאי טפשאי וכו' לא שמיע להו הא דאמר ר\"י מחלוקת בשבדק ולא מצא וכו' ור' אסי אמר ר\"י מחלוקת בשבדק ומצא משמע דליתא להא דר\"נ והיאך פסק רבינו כמותו. וי\"ל דמשמע דלא פליגי אלא בפירושא דברייתא היכי מיתוקמא שפיר טפי אבל לענין דינא לא פליגי עליה:",1,0],[3,13,"האורג מלא הסיט מצמר הבכור וכו'. בפ\"ג דערלה (משנה ג') האורג מלא הסיט מצמר בכור בבגד ידלק הבגד וכתב הר\"ש מוקי לה בשלהי תמורה (דף ל\"ד.) בדעבד מיניה צפרתא דחשיב ולא בטיל הא לאו הכי שרי דבטיל ברובא. ופירש\"י שעשה מהאיסור צורת צפור דחשיב דמיפה ליה לכוליה [שק] ולא מיבטיל. ורבינו שלא חילק בין עבד מיניה צפרתא ללא עבד נראה שטעמו משום דלא מוקי בגמרא בדעבד מיניה צפרתא אלא למאי דקתני התם משער נזיר ומפטר חמור בשק ידלק השק וסובר רבינו דלא ילפינן מיניה לבכור אע\"ג דכי הדדי מיתני במסכת ערלה דדוקא בשער נזיר ופטר חמור דלא חשיב הוא דפריך וליבטיל ברובא ואיצטריך לשנויי דעבדיה כצפרתא אבל גבי צמר בכור ל\"ק לן דליבטיל ברובא דמלא הסיט צמר חשיב ולא בטיל אפי' בכמה אבל קשה על זה דגם בדין שער בשק לא חילק בסוף הל' פסולי המוקדשין. והר\"י קורקוס ז\"ל כתב שרבינו מפרש דלאו דוקא שארג צפרתא אלא ה\"ק כיון שהוא מלא הסיט שראוי לצפרתא חשיב ולא בטיל דאי בעשה צפרתא דוקא מלא הסיט למה הוזכר. א\"נ שסובר רבינו שאותה קושיא ואותו תירוץ הם דלא כהלכתא דהא קי\"ל דבגד שאבד בו כלאים אינו בטל והא נמי דכוותה אע\"פ שחילקו המפרשים לשאר איסורים רבינו אינו מחלק:",2,0],[3,13,"וכתב הראב\"ד גיזת בכור אפילו בעל מום וכו' קשיא לן בטווי וארוג בעינן מלא הסיט וכו'. ואיכא למידק עליה לתירוצא קמא טווי וארוג דבעינן מלא הסיט ע\"כ בנגזז מן החי היא דאילו אחר מיתה מותר ליהנות בגיזותיו כמ\"ש רבינו בפ' זה וכיון שכן למה גזרו בגיזה יותר מבטווי וארוג הבא מן הגיזה. ולכן נ\"ל שצריך להגיה ולגרוס א\"כ במקום א\"נ וכוליה חד תירוצא הוא וה\"ק כיון דגיזה לא מיתסר אלא משום קנסא לא קנסו שיאסר בכל שהו אלא כשהוא בגיזה אבל כשנשתנה לטווי וארוג לא גזרו שיאסר בכל שהוא והוקשה לו א\"כ למה במוקדשים טווי ואריג מקדשין בכל שהן ותירץ דמיירי בקדשים שיש להם פדיון ומשום דדבר שיש לו מתירין אפילו באלף לא בטל:",3,0],[4,1,"בהמת השותפין חייבת בבכורה וכו'. פלוגתא דתנאי בר״פ ראשית הגז (חולין דף קל״ה) ופסק כת״ק.",1,0],[4,1,"ומ\"ש שאם היה שותף בפרה או בעובר אפילו היה לנכרי אחד מאלף וכו'. טעמו דכיון דיש לו חלק בכל הבהמה אפילו הוא אחד מאלף שותף מיקרי ואמרינן בריש בכורות (דף ג') בכור מקצת בכור משמע כתב רחמנא כל עד דאיכא כוליה.",2,0],[4,1,"ומ\"ש באם או בולד. הכי אמרינן בריש בכורות (דף ב'):",3,0],[4,1,"ומ\"ש היה לו באחד משניהם אבר אחד וכו'. שם (דף ג') וכמה תהא שותפות של נכרי ותהא פטורה מן הבכורה כלומר כשהנכרי אינו שותף אלא באבר אחד במה תהא שותפותו ויפטור מן הבכורה אמר רב הונא אפילו אזנו מתקיף לה ר\"נ ולימא ליה שקול אזנך וזיל אתמר רב חסדא אמר דבר שעושה אותו נבלה ורבא אמר דבר שעושה אותו טריפה ובתר הכי אר\"י אפילו מום קל. ופירש\"י אפי' אין לנכרי שותפות אלא באזנה שאם היה נוטל חלקו אינה לא נבילה ולא טריפה אלא מום קל בעלמא פטורה מן הבכורה ופסק רבינו כר\"י ורב הונא. וא\"ת היכי משכחת לה שיחתך שום אבר ולא תהיה בעלת מום. וי\"ל דמשכחת לה כגון שהיה יתר אצבע בידו או ברגלו ואין בו עצם שאם חתכו כשר:",4,0],[4,2,"הלוקח עובר פרתו של נכרי וכו'. משנה בפרק ב' דבכורות (דף י\"ג).",1,0],[4,2,"ומ\"ש ואין קונסין אותו על דבר זה. הכי איכא למילף משקלא וטריא דריש בכורות:",2,0],[4,3,"המקבל בהמה מן הנכרי וכו'. בריש בכורות (דף ב':) ר\"י אומר המקבל בהמה מן הנכרי וילדה מעלים אותה בשיווי ונותן חצי דמיו לכהן והנותן לו בקבלה כו' נותן כל דמיו לכהן וחכמים אומרים כל זמן שיד נכרי באמצע פטורה מן הבכורה וידוע דהלכה כחכמים:",1,0],[4,4,"המקבל צאן מן הנכרי בממון קצוב וכו'. משנה בפרק ב' דבכורות (דף ט\"ז:) ואיפלגו בה אמוראי ורבינו נתן כלל בדבר דכל ולדות שיש רשות לנכרי לגבות מהם פטורים וכל ולדות שאין לו רשות לגבות מהם חייבים ולדוגמא נקט ולדות וולדי ולדות ומפני כך השמיט מה ששנו במשנה העמיד ולדות תחת אמותיהם ולדי ולדות פטורים ולדי ולדי ולדות חייבים ולא איפלגו אמוראי אלא בכמה דורות הוא דרך להיות אחריות הנכרי עליהם ולדברי הכל דין זה שכתב רבינו אמת:",1,0],[4,5,"ישראל שנתן מעות לנכרי וכו' וכן אם קנה הנכרי מישראל בדיניהם וכו'. מימרא ברפ\"ב דבכורות (דף י\"ג):",1,0],[4,6,"גר שנתגייר וכו'. בסוף פרק הזרוע (חולין דף קל״ד):",1,0],[4,7,"הלוקח בהמה מן הנכרי וכו'. משנה בריש פרק ג' דבכורות (דף י\"ט:) אם ספק יאכל במומו לבעלים:",1,0],[4,8,"לקח בהמה מניקה מן הנכרי וכו'. גם זה משנה שם (דף כ\"ג:) ואיפסיקא בגמ' הלכתא כרשב\"ג דמתני'.",1,0],[4,8,"ומ\"ש ואפילו היה זה שמניקה כמו מין אחר ואפילו כמין חזיר וכו'. מימרא דרבי יוחנן שם (דף כ\"ד).",2,0],[4,8,"ומ\"ש וכן בהמה שהיא חולבת וכו'. בפ\"ג דבכורות (דף כ\"ו:) פלוגתא דר' יהושע ור\"ע ופסק כר' יהושע דרביה הוא:",3,0],[4,9,"הלוקח בהמה מישראל הרי זה בחזקת שבכרה וכו'. שם (דף כ\"א:) פלוגתא דאמוראי ופסק כר' יוחנן:",1,0],[4,10,"בהמה דקה שהפילה עובר וכו'. משנה וגמ' בר\"פ הנזכר (דף י\"ט כ') ובדף הנזכר בגמרא:",1,0],[4,10,"לפיכך הלוקח בהמה מן הנכרי וכו'. בריש פרק הנזכר פלוגתא דתנאי ופסק כרבי עקיבא:",2,0],[4,10,"וכן בהמה [גסה] שהפילה שליא הרי זה סימן ולד וכו'. משנה שם ופ' בהמה המקשה:",3,0],[4,10,"ומה שכתב ומותר להשליך אותה שליא לכלבים וכו' אבל בהמת קדשים שהפילה שליא תקבר וכו'. משנה (דף ע\"ז) וגמרא פרק בהמה המקשה:",4,0],[4,11,"בהמה גסה שהפילה חררת דם וכו'. משנה פרק ג' דבכורות (דף כ\"א:)",1,0],[4,11,"ומ\"ש ולמה קוברים אותו וכו'. שם בגמ' ואע\"פ שטעם זה נאמר בגמ' לר\"ש דאמר דאינה מטמאה לדידן נמי צ\"ל כן כי היכי דלא תיקשי לן מ\"ש משליא דישליכנה לכלבים וכ\"כ התוס':",2,0],[4,12,"כבר ביארנו בענין נדה וכו' אבל ולד בהמה לא עמדו חכמים על מניין הימים שיגמר בו. שם (דף כ\"א:).",1,0],[4,12,"ומ\"ש אבל אמרו שהמפלת טינוף אינה מתעברת אחריו וכו'. מימרא דזעירי שם (דף כ'):",2,0],[4,13,"בהמה שיצאה מליאה ובאתה ריקנית וכו'. פ' המפלת (דף נ\"ט):",1,0],[4,13,"ואין לנפלי בהמה פטירת רחם וכו'. בפ' שלישי דבכורות (דף נ\"ב).",2,0],[4,13,"ומ\"ש של ערב. מימרא דרבי יוחנן שם. פ' הערוך פיקה כמו כדור קטן שמשימים בראש הכוש שטוים בו ואותו שטוים בו השתי קטן מאותו שטוים בו הערב:",3,0],[4,13,"כתב הראב\"ד ז\"ל א\"א דגרסינן בבכורות שמעתי וכו':",4,0],[4,14,"מבכרת המקשה לילד וכו'. משנה פרק בהמה המקשה (חולין דף ס\"ט:) ומפרש רבינו דמאי דקתני נפטרה מן הבכורה אסיפא דוקא קאי ולא כרש\"י שפירש דארישא נמי קאי.",1,0],[4,14,"ומה שכתב ואם חתך אבר והניחו וכו' נתקדש למפרע. שם בגמרא אליבא דרב הונא דהלכה כוותיה כדבסמוך:",2,0],[4,15,"ומ\"ש יצא שליש ומכרו לנכרי וכו' יצא שליש דרך דופן וכו'. שם פלוגתא דרב הונא ורבה ופסק כרב הונא:",1,0],[4,16,"יצא מיעוט אבר גדול וכו'. פשוט שם.",1,0],[4,16,"ומ\"ש יצא חצי העובר והוא רובו של אבר היוצא וכו'. שם (דף ע') בעיא דלא איפשיטא:",2,0],[4,17,"בכור שכרכו בסיב וכו'. שם בעיי דלא איפשיטו וגירסת רבינו כגירסת ר\"ח שכתבו התוספות:",1,0],[4,20,"הדביק שני רחמים זה לזה וכו' נפתחו כותלי בית הרחם וכו' נעקרו בית הרחם [ונתלו] בצוארו הרי זה ספק. שם בעיי דלא איפשיטו:",1,0],[4,21,"נגממו כותלי בית הרחם אינו קדוש. בעיא שם וא\"ל נגעת בבעיא דאבעיא לן דבעי ר' זירא מר' אסי עומד מרובה על הפרוץ ויצא דרך פרוץ פרוץ מרובה על העומד ויצא דרך עומד מאי ע\"כ לא איבעיא לי אלא פרוץ מרובה על העומד דאיכא עומד בעולם אבל נגממו לא קא מיבעיא לי. ופירש רש\"י נגממו ניטל מעובי הכותלים מבפנים סביב סביב וכו' ל\"א נגממו מבפנים ושפה חיצונה משמרת עכ\"ל ופירוש ראשון נראה יותר:",1,0],[5,1,"רחל שלא בכרה וכו'. בפרק ב' דבכורות (דף י\"ז) פלוגתא דרבי יוסי הגלילי וחכמים במשנה ופסק כחכמים.",1,0],[5,1,"ומ\"ש הכהן נוטל את הכחוש. שם במשנה פלוגתא דר\"ע ור\"ט ופסק כר\"ע.",2,0],[5,1,"ומ\"ש והשני ספק בכור. שם במשנה.",3,0],[5,1,"ומ\"ש מת אחד מהם אין לכהן כלום וכו'. שם במשנה פלוגתא דר\"ע ור\"ט ופסק כר\"ע.",4,0],[5,1,"מ\"ש וכן אם ילדה זכר ונקבה וכו'. שם (דף י\"ח) במשנה:",5,0],[5,2,"שתי רחלות שלא בכרו וכו' עד שזה הזכר ספק בכור הוא. הכל משנה שם:",1,0],[5,3,"כל בכור שהוא ספק דינו שירעה וכו'. פשוט שם במשנה.",1,0],[5,3,"ומ\"ש ואם תפשו הכהן וכו'. נתבאר בפרק שני.",2,0],[5,3,"ומ\"ש אבל אינו מקריבו וכו'. פשוט הוא:",3,0],[5,4,"מי שהיה בעדרו מבכרות וכו'. משנה פרק שלישי דבכורות (דף כ\"ג:):",1,0],[5,6,"שנים שהפקידו שני זכרים וכו'. פ\"ב דבכורות (דף י\"ח:) הכל מודים בשנים שהפקידו אצל רועה שמניח רועה ביניהם ומסתלק וכו' ובאחד שהפקיד אצל בעל הבית שהמוציא מחבירו עליו הראיה לא נחלקו אלא בחצר בעה\"ב ורועה כהן ר\"ט סבר אקנויי קא מקני ליה בחצירו וניחא ליה דלתעביד מצוה וה\"ל כשנים שהפקידו אצל רועה שמניח רועה ביניהם ומסתלק ור\"ע סבר כיון דאית ליה פסידא לא מקני ליה מדעם וה\"ל כאחד שהפקיד אצל בעה\"ב שהמע\"ה ופסק הלכה כר\"ע:",1,0],[5,7,"לא נחשדו ישראל על הבכורות וכו'. בפרק כל פסולי המוקדשין (בכורות ל״ו:):",1,0],[5,8,"כל הקדשים שקדם להם מום קבוע להקדשן וכו'. משנה פ״ב דבכורות (דף י״ד) ופרק הזרוע (חולין דף ק״ל):",1,0],[5,9,"הלוקח בהמה ממעות מעשר שני וכו'. ירושלמי פ\"ק דמעשר שני וכרבי זעירא דמסייעא ליה מתניתא:",1,0],[5,9,"אבל הלוקח בהמה וכו'. בספ\"ק דבכורות (דף י\"ב:) אמר רב חסדא בהמת שביעית פטורה מן הבכורה וכו' לאכלה אמר רחמנא ולא לשריפה ופירש\"י לשריפה ואי מיחייב בבכור סלקי אימורים לגבוה עכ\"ל. והראב\"ד השיג על רבינו שכתב ולא לסחורה ולא ה\"ל לכתוב אלא ולא לשריפה כמו שאמרו בגמרא. ונראה שבנוסחת רבינו היה כתוב ולא לסחורה.",2,0],[5,9,"ומ\"ש רבינו הרי זה משתכר בבכור היינו לומר שאינו חייב לבערו בזמן הביעור ונותנו לכהן ויש לו טובת הנאה:",3,0],[5,9,"וכן אסור לעשות סחורה בבכורות וכו'. בפ\"ז דשביעית:",4,0],[5,10,"ומ\"ש לקח בכור למשתה בנו וכו'. גם זה משנה שם:",1,0],[5,11,"אין שמין בכורות תמימים לישראל וכו'. תוספתא בפ\"ג דבכורות, וכתב רבינו בזמן הזה כלומר דאי בזמן הבית קרב הוא ונאכל לכהנים בלבד ומאי שומא איכא:",1,0],[6,1,"מצות עשה להפריש אחד מעשרה וכו'. בת\"כ פרשת בחקותי:",1,0],[6,2,"מעשר בהמה נוהג בחולין. משנה בר\"פ בתרא דבכורות (דף נ\"ג).",1,0],[6,2,"ומ\"ש אבל חכמים אסרו לעשר בהמה בזמן הזה וכו'. שם בגמרא.",2,0],[6,2,"ומה שכתב ואם עבר ועשה וכו'. פשוט הוא דכיון שאין הטעם אלא משום דלא ליתי לידי תקלה היכא דעבר ועישר למה לא יהיה קדוש:",3,0],[6,3,"הכל חייבים במעשר בהמה וכו':",1,0],[6,4,"ודין מעשר בהמה שיהיה נשחט בעזרה וכו'. משנה בס״פ איזהו מקומן (זבחים נ״ו:).",1,0],[6,4,"ומ\"ש ואם היה בעל מום וכו'. בפ' בתרא דבכורות (דף נ\"ז) אמרינן דמעשר לא פסיל ביה מומא:",2,0],[6,5,"מעשר בהמה אסור למכרו כשהוא תמים וכו'. בפ״ק דמעשר שני תנן מעשר בהמה אין מוכרים אותו תמים חי ולא בעל מום חי ושחוט וכתב ה״ר עובדיה תמים חי והה״נ שחוט וכו' ואיידי דבעי למיתני סיפא גבי בכור מוכרים אותו תמים חי תנא נמי רישא תמים חי. ובפ״ק דתמורה (דף ה':) ובר״פ כל פסולי המוקדשין (בכורות דף ל״א:) תניא במעשר נאמר לא יגאל ואינו נמכר לא חי ולא שחוט ולא תם ולא בעל מום ופירש״י לא יגאל ואינו נמכר דגמרינן מלא יגאל (דחרמים) כדלקמן:",1,0],[6,6,"ומ\"ש מד\"ס שאסור למוכרו בעל מום ואפילו שחוט וכן מ\"ש שזה מד\"ת וזה מד\"ס. בר\"פ כל פסולי המוקדשין אמר רבא מנא אמינא לה (דמעשר בהמה שנשחט מותר למוכרו בהבלעה) דכתיב והיה הוא ותמורתו יהיה קדש לא יגאל אימתי עושה תמורה מחיים אימתי אינו נגאל מחיים הא לאחר שחיטה נגאל ורבנן הוא דגזרו לאחר שחיטה אטו לפני שחיטה וכו' דבר שאינו נישום מחיים לא גזרו ביה רבנן פירוש דבר המתחשב מחיים כי עיקר קונה הבהמה מחיים אינו מחשיב לא העור והגידים והחלב, ולפי זה הא דתניא במעשר נאמר לא יגאל ואינו נמכר לא חי ולא שחוט לא תם ולא בעל מום אסמכתא בעלמא היא דמדאורייתא לא מיתסרא מכירתו אלא תמים חי דומיא דתמורה:",1,0],[6,6,"ומ״ש לפיכך אין שוקלין מנה כנגד מנה במעשר וכו'. הכי משמע במתני' ר״פ כל פסולי המוקדשין (בכורות דף ל״א) דקתני ושוקלין מנה כנגד מנה בבכור ומשמע דוקא בבכור אבל לא במעשר:",2,0],[6,7,"ומעשר בהמה של יתומים וכו'. בריש פרק כל פסולי המוקדשין שם:",1,0],[6,8,"מעשר בהמה שנשחט במומו וכו' עד בהבלעה מותר. שם וכתבתיו בסמוך.",1,0],[6,8,"ומ\"ש ואם היו דמי העצמות יקרים וכו'. שם פלוגתא ופסק לקולא כדרבנן:",2,0],[6,9,"הכל נאמנים על מומי מעשר וכו'. משנה בסוף פרק כל פסולי המוקדשין (בכורות דף ל״ו:) ומפרש טעמא בגמרא משום דאי בעי שדי מומא בכוליה עדריה.",1,0],[6,9,"ומ\"ש ורואה אדם מומי מעשר שלו ומתירו אם היה מומחה. מבואר [שם ל\"א] מהטעם הנזכר:",2,0],[6,10,"הלוקח טלאים שנולדו בשנה זו וכו' לפיכך השותפים שנשתתפו בבהמות וכו' עד אחר שיתוף זה השני. הכל משנה בפרקא בתרא דבכורות (דף נ\"ה: ונ\"ו:).",1,0],[6,10,"ומ\"ש ואע\"פ שחלקו גדיים כנגד גדיים וכו'. שם פלוגתא דאמוראי ופסק כר\"נ וכתוב בספרי רבינו וטלאים כנגד גדיים וט\"ס הוא וצריך להגיה ולכתוב וטלאים כנגד טלאים.",2,0],[6,10,"ומ\"ש ועשרה כנגד עשרה. שם פלוגתא דאמוראי ופסק כר\"י:",3,0],[6,11,"האחין והשותפין שחלקו בכספים וכו' אבל אם חלקו הבהמות כו'. מימרא דר' ירמיה שם (דף נ\"ו:):",1,0],[6,12,"הלוקח עשרה עוברים וכו'. מימרא דר\"י בדף הנזכר:",1,0],[6,13,"כהן שנפלו לו עשר בהמות וכו'. בס״פ הגוזל עצים (בבא קמא דף ק״י:) בעיא דאיפשיטא:",1,0],[6,14,"הכל נכנסים לדיר להתעשר וכו' עד אינו מתעשר. משנה וגמרא בפירקא בתרא דבכורות (דף נ\"ז). ודע דאמרינן בפירקא קמא דזבחים ליל שמיני נכנס לדיר להתעשר ואיני יודע למה השמיטו רבינו:",1,0],[6,15,"אין הלוקח פטור וכו' לפיכך הלוקח טלאים בתוך שבעת ימי הלידה וכו'. שם (דף נ\"ו) אמרינן דברייתא דקתני דלקוח חל על מחוסר זמן אינה משנה ואת\"ל משנה רבי שמעון בן יהודה היא ומשמע דחכמים פליגי עליה והלכתא כוותייהו:",1,0],[6,16,"כל בהמה שהיא ספק וכו'. נלמד מהדין שיבא בסוף הלכות אלו והוא בפ' הנזכר (דף נ\"ח:) קפץ אחד מהמנויים לתוכם כולם פטורים ובתוספתא דסוף בכורות תניא נתערב בהם יתום או לקוח כולם פטורים:",1,0],[7,1,"מי שהיו לו עשרה טלאים וכו'. במשנה פרק בתרא דבכורות (דף נ\"ח:) פלוגתא דתנאי ופסק כת\"ק:",1,0],[7,1,"כיצד עושה וכו'. שם במשנה.",2,0],[7,1,"ומ\"ש ואמותיהם מעמיד מבחוץ וכו'. ברייתא וגמרא שם [ובתוספתא דבכורות שם].",3,0],[7,1,"ומ\"ש מתחיל ומונה אותם בשבט וכו' עד וקידש עשירי ה\"ז מעשר. שם במשנה:",4,0],[7,2,"אין צריך לצרף וכו'. נלמד ממה שיבא בסמוך:",1,0],[7,2,"היו לו חמשה טלאים בירושלים וכו' עד ט\"ז מיל. במשנה פ' בתרא דבכורות (דף נ\"ד:):",2,0],[7,3,"ומ\"ש היו ג' עדרים וכו' עד להתעשר. שם פלוגתא דרב ושמואל ופסק כרב באיסורי:",1,0],[7,4,"אין מעשרים מן הצאן על הבקר וכו'. משנה שם (דף נ\"ג):",1,0],[7,5,"אין מעשרים מן הנולדים בשנה זו וכו'. משנה וגמרא שם:",1,0],[7,6,"כל הנולדים מאחד בתשרי עד כ\"ט באלול וכו' עד אין מצטרפין. משנה בפרק בתרא דבכורות (דף נ\"ז:):",1,0],[7,6,"ילדו תולדות בתוך שנתן וכו'. כן משמע בתוספתא דבכורות פ\"ז:",2,0],[7,7,"אין הטלאים הנולדים כמו הטבל וכו'. מתבאר ממה שיבא בסמוך:",1,0],[7,8,"קבעו חכמים ג' זמנים בשנה וכו'. פ' בתרא דבכורות (דף נ\"ז:) פלוגתא דתנאי ופסק כר\"ע.",1,0],[7,8,"ומ\"ש ואם שחט ה\"ז מותר. משנה שם:",2,0],[7,8,"ומ\"ש ולמה קבעו הגרנות בימים אלו וכו'. שם בגמרא (דף נ\"ח):",3,0],[7,9,"הכניס כל הצאן וכו'. שם (דף נ\"ט:) מימרא דרבא וברייתא.",1,0],[7,9,"ומ\"ש ואע\"פ שידע שאלו ישארו במניין וכו'. שם:",2,0],[8,1,"המכניס צאן לדיר וכו'. ברייתא בסוף בכורות (דף ס':) ומשנה בנזיר פרק בית שמאי (נזיר דף ל״א).",1,0],[8,1,"ומה שכתב אבל אם קרא לתשיעי או לאחד עשר עשירי וכו' עד מפני שהוא עצמו כתמורה. משנה בפירקא בתרא דבכורות:",2,0],[8,2,"ומ\"ש וטעון נסכים כשלמים: ומה שכתב ואינו עושה תמורה. בסוף בכורות (דף ס') במשנה פלוגתא דר\"מ ור\"י ופסק כר\"י.",1,0],[8,2,"ומה שכתב במה דברים אמורים כשהיה המונה הוא בעל הבהמות וכו'. מימרא בסוף בכורות (דף ס\"א) ופסק כרב פפא לגבי רב פפי והכי קיימא לן בכל דוכתא דטעות שליח בכל שהוא דאמר לי' לתקוני שדרתיך ולא לעוותי:",2,0],[8,3,"זה שאמרנו שאם קרא וכו'. משנה שם (דף ס').",1,0],[8,3,"ומה שכתב ואפילו יצא העשירי ולא קראהו לא עשירי ולא אחד עשר וכו'. ברייתא שם (בדף נ\"ט):",2,0],[8,4,"יצאו ט' וי' כאחד וכו' וכן אם יצאו עשירי וי\"א כאחד וכו'. מימרא דרבא (בדף ס'):",1,0],[8,5,"התחיל למנות ויצאו וכו'. משנה שם.",1,0],[8,5,"ומ\"ש וכן אם מנאן ג' ג' בכל פעם ופעם וכו'. שם פלוגתא דאמוראי ופסק כר\"י דאמר מונאן זוגות זוגות קינטרין קינטרין י' למניינן הוא קדוש וכדפריש רב מרי למניין שלו הוא קדוש ומשמע דרבא סבר כוותיה מדמתרץ ברייתא אליביה:",2,0],[8,6,"יצאו בתחלה שנים וכו'. שם במשנה:",1,0],[8,7,"מנאן למפרע וכו'. שם (בדף ס'):",1,0],[8,8,"קרא לתשיעי עשירי ונשאר העשירי בדיר וכו' עד שהמנין הראוי פוטר. שם (דף נ\"ט ע\"ב):",1,0],[8,9,"הכניס י' טלאים וכו' עד שהרי ששה היו שם נשארים בתוך הדיר. שם בדף הנזכר:",1,0],[8,11,"מי שהיו לו תשעה עשר טלאים וכו' עד שאותן התשעה נמנו מניין הראוי. גם זה בדף הנזכר (ובדף ס'):",1,0],[8,12,"היה מונה והוציא הטלה ראשו וכו'. הכי משמע שם (בדף ס'):",1,0],[8,13,"היה מונה והפסיק וכו'. בתוספתא בסוף בכורות:",1,0],[8,14,"היה מונה היוצאים וכו' עד סוף הפרק. משנה בפרק בתרא דבכורות (דף נ\"ח:):",1,0],[8,14,"סליקו הלכות בכורות בס\"ד",2,0]]);
